static std::vector<char> read(const std::wstring&p){std::ifstream f(p.c_str(),std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("input missing");auto n=f.tellg();if(n<=0||n>64*1024*1024)throw std::runtime_error("input size");std::vector<char>v(static_cast<size_t>(n));f.seekg(0);if(!f.read(v.data(),n))throw std::runtime_error("input read");return v;}
static void save(const std::wstring&p,const std::vector<char>&v){std::ofstream f(p.c_str(),std::ios::binary);if(!f.write(v.data(),v.size()))throw std::runtime_error("output write");}
